bool isPal(String s) {
  var l = 0, r = s.length - 1;
  while (l < r) {
    if (s[l] != s[r]) return false;
    l++;
    r--;
  }
  return true;
}

void main() {
  print(isPal('level'));
  print(isPal('levels'));
}
```

