String compress(String s) {
  final out = StringBuffer();
  var count = 1;
  for (var i = 1; i <= s.length; i++) {
    if (i < s.length && s[i] == s[i - 1]) {
      count++;
    } else {
      out
        ..write(s[i - 1])
        ..write(count);
      count = 1;
    }
  }
  return out.toString();
}

void main() {
  print(compress('aabbbc'));
}
```

